18	    fwrite(STDERR, 'PHPUnit is not installed. Require phpunit/phpunit before running tests.' . PHP_EOL);
19	    exit(1);
20	}
21	
22	$phpUnitVersion = InstalledVersions::getVersion('phpunit/phpunit');
23	
24	if ($phpUnitVersion === null) {
25	    fwrite(STDERR, 'The installed phpunit/phpunit package does not expose a version. Install a tagged release.' . PHP_EOL);
26	    exit(1);
27	}
28	
29	$phpUnitMajor = explode('.', $phpUnitVersion)[0];
30	$configurations = [
31	    '9' => 'phpunit9.xml.dist',
32	    '10' => 'phpunit10.xml.dist',
33	    '11' => 'phpunit11.xml.dist',
34	    '12' => 'phpunit12.xml.dist',
35	    '13' => 'phpunit.xml.dist',
36	];
37	$configuration = $configurations[$phpUnitMajor] ?? null;
38	
39	if ($configuration === null) {
40	    fwrite(STDERR, sprintf(
41	        'Installed PHPUnit major %s is unsupported. Add its configuration to the test runner map.',
42	        $phpUnitMajor,
43	    ) . PHP_EOL);
44	    exit(1);
45	}
46	
47	$configurationPath = $packageRoot . '/' . $configuration;
48	
49	if (!is_file($configurationPath)) {
50	    fwrite(STDERR, sprintf(
51	        'PHPUnit %s requires %s next to this package\'s composer.json.',
52	        $phpUnitMajor,
53	        $configuration,
54	    ) . PHP_EOL);
55	    exit(1);
56	}
57	
58	$rawArguments = $_SERVER['argv'] ?? null;
59	
60	if (!is_array($rawArguments)) {
61	    fwrite(STDERR, 'CLI arguments are unavailable. Run tests/run.php from the command line.' . PHP_EOL);
62	    exit(1);
63	}
64	
65	$arguments = [];
66	
67	foreach (array_slice($rawArguments, 1) as $argument) {
68	    if (!is_string($argument)) {
69	        fwrite(STDERR, 'A CLI argument is invalid. Pass only string arguments to tests/run.php.' . PHP_EOL);
70	        exit(1);
71	    }
72	
73	    $arguments[] = $argument;
74	}
75	
76	$parallel = ($arguments[0] ?? null) === '--parallel';
77	
78	if ($parallel) {
79	    array_shift($arguments);
80	}
81	
82	$runner = $packageRoot . '/vendor/bin/' . ($parallel ? 'paratest' : 'phpunit');
83	
84	if (!is_file($runner)) {
85	    fwrite(STDERR, sprintf(
86	        '%s is not installed. Require the matching development dependency first.',
87	        $parallel ? 'ParaTest' : 'PHPUnit',
88	    ) . PHP_EOL);
89	    exit(1);
90	}
91	
92	$memoryLimit = ini_get('memory_limit');
93	
94	if ($parallel) {
95	    array_unshift($arguments, '--passthru-php=-d memory_limit=' . $memoryLimit);
96	}
97	
98	$command = array_map(
99	    static fn (string $argument): string => escapeshellarg($argument),
100	    [
101	        PHP_BINARY,
102	        '-d',
103	        'memory_limit=' . $memoryLimit,
104	        $runner,
105	        '--configuration',
106	        $configurationPath,
107	        ...$arguments,
108	    ],
109	);
110	
111	passthru(implode(' ', $command), $exitCode);
112	exit($exitCode);
