          }
        ]
      }
    ]
  },
  "permissions": {
    "deny": [
      "Edit(/.claude/settings.json)",
      "Edit(/.php-cs-fixer.dist.php)",
      "Edit(/AGENTS.md)",
      "Edit(/CLAUDE.md)",
      "Edit(/deptrac.yaml)",
      "Edit(/error-formatter.neon)",
      "Edit(/extension.neon)",
      "Edit(/infection.json5)",
      "Edit(/loc.yaml)",
      "Edit(/phpcs.xml.dist)",
      "Edit(/phpstan.neon)",
      "Edit(/phpunit*.xml.dist)",
      "Edit(/rules.neon)",
      "Edit(/tree.yaml)",
      "Bash(*.claude/settings.json*)",
      "Bash(*.php-cs-fixer.dist.php*)",
      "Bash(*AGENTS.md*)",
      "Bash(*CLAUDE.md*)",
      "Bash(*deptrac.yaml*)",
      "Bash(*error-formatter.neon*)",
      "Bash(*extension.neon*)",
      "Bash(*infection.json5*)",
      "Bash(*loc.yaml*)",
      "Bash(*phpcs.xml.dist*)",
      "Bash(*phpstan.neon*)",
      "Bash(*phpunit*.xml.dist*)",
      "Bash(*rules.neon*)",
      "Bash(*tree.yaml*)"
    ]
  }
}

