30	        return $value;
31	    }
32	    /**
33	     * @param mixed $value
34	     * @return list<string>
35	     * @throws PolicyException when a path list is invalid
36	     */
37	    public function strings($value, string $context): array
38	    {
39	        if (!is_array($value) || array_values($value) !== $value) {
40	            throw new PolicyException($context . ' must be a list of strings.');
41	        }
42	        $result = [];
43	        foreach ($value as $entry) {
44	            $result[] = $this->string($entry, $context);
