5	namespace Guard\Config;
6	
7	use Guard\Diagnostic\PolicyException;
8	use Symfony\Component\Yaml\Exception\ParseException;
9	use Symfony\Component\Yaml\Yaml;
10	
11	/**
12	 * Loads a guard document and the documents it imports.
13	 *
14	 * Paths are relative to the file that lists them. Later imports override earlier ones, and the current file overrides its imports.
15	 */
16	final class ImportResolver
17	{
18	    /**
19	     * @var list<string>
20	     */
21	    private array $seen = [];
22	
23	    /**
24	     * @var list<string>
25	     */
26	    private array $paths = [];
27	
28	    /**
29	     * Loads one guard document, following its imports.
30	     *
31	     * @return array<string, mixed>
32	     * @throws PolicyException when the file is missing, circular, or not a version 1 document
33	     */
34	    public function resolve(string $path, bool $root = true): array
35	    {
36	        if (!is_file($path)) {
37	            $message = $root
38	                ? 'Guard configuration not found: ' . $path . '. Run guard init first.'
39	                : 'Guard import not found: ' . $path . '. Check that the path is relative to the file that lists it.';
40	            throw new PolicyException($message);
41	        }
42	        $identity = realpath($path);
43	        $identity = $identity === false ? $path : $identity;
44	        if (in_array($identity, $this->seen, true)) {
45	            throw new PolicyException('Circular guard import: ' . implode(' -> ', array_merge($this->paths, [$path])) . '. Remove the repeated import.');
46	        }
47	        $this->seen[] = $identity;
48	        $this->paths[] = $path;
49	        try {
50	            return $this->document($path, $root);
51	        } finally {
52	            array_pop($this->seen);
53	            array_pop($this->paths);
54	        }
55	    }
56	
57	    /**
58	     * Parses one document, loads its imports, and overlays the document on those imports.
59	     *
60	     * @return array<string, mixed>
61	     * @throws PolicyException when the document is malformed
62	     */
63	    public function document(string $path, bool $root): array
64	    {
65	        $data = $this->mapping($path, $root);
66	        $this->version($data, $path, $root);
67	        $this->assertUnique($data, $path);
68	        $merged = [];
69	        foreach ($this->imports($data['imports'] ?? null, $path, $root) as $import) {
70	            $merged = (new DocumentMerger())->merge($merged, $this->resolve($import, false));
71	        }
72	        unset($data['imports']);
73	
74	        return (new DocumentMerger())->merge($merged, $data);
75	    }
76	
77	    /**
78	     * Reads a YAML mapping and rejects unknown top-level keys.
79	     *
80	     * @return array<string, mixed>
81	     * @throws PolicyException when the YAML cannot be parsed or contains unknown keys
82	     */
83	    public function mapping(string $path, bool $root): array
84	    {
85	        try {
86	            $parsed = Yaml::parseFile($path);
87	        } catch (ParseException $exception) {
88	            $name = $root ? 'guard.yaml' : basename($path);
89	            throw new PolicyException('Invalid ' . $name . ': ' . $exception->getMessage() . '. Correct the YAML syntax.', 0, $exception);
90	        }
91	        $context = $root ? 'guard.yaml' : basename($path);
92	
93	        return (new Schema())->mapping($parsed, ['version', 'imports', 'metrics', 'structure', 'documentation', 'configuration', 'extensions', 'collect'], $context);
94	    }
95	
96	    /**
97	     * Requires version 1 on the project file and on any imported file that sets version.
98	     *
99	     * @param array<string, mixed> $data
100	     * @throws PolicyException when version is missing on the project file or is not 1
101	     */
102	    public function version(array $data, string $path, bool $root): void
103	    {
104	        if (!array_key_exists('version', $data)) {
105	            if ($root) {
106	                throw new PolicyException('guard.yaml.version must be 1. Use guard init to generate the current schema.');
107	            }
108	
109	            return;
110	        }
111	        if ($data['version'] !== 1) {
112	            $name = $root ? 'guard.yaml' : basename($path);
113	            throw new PolicyException($name . '.version must be 1. Use guard init to generate the current schema.');
114	        }
115	    }
116	
117	    /**
118	     * Rejects two configuration rules with the same id in one file.
119	     *
120	     * @param array<string, mixed> $data
121	     * @throws PolicyException when a file repeats a configuration rule id
122	     */
123	    public function assertUnique(array $data, string $path): void
124	    {
125	        $rules = $data['configuration'] ?? null;
126	        if (!is_array($rules) || array_values($rules) !== $rules) {
127	            return;
128	        }
129	        $seen = [];
130	        foreach ($rules as $rule) {
131	            if (!is_array($rule) || !is_string($rule['id'] ?? null) || $rule['id'] === '') {
132	                continue;
133	            }
134	            if (isset($seen[$rule['id']])) {
135	                throw new PolicyException('Duplicate configuration rule "' . $rule['id'] . '" in ' . $path . '. Give each rule a unique id in that file.');
136	            }
137	            $seen[$rule['id']] = true;
138	        }
139	    }
140	
141	    /**
142	     * Resolves import paths from the directory of the file that lists them.
143	     *
144	     * @param mixed $value
145	     * @return list<string>
146	     * @throws PolicyException when imports is not a list of paths
147	     */
148	    public function imports($value, string $path, bool $root): array
149	    {
150	        if ($value === null) {
151	            return [];
152	        }
153	        $context = ($root ? 'guard.yaml' : basename($path)) . '.imports';
154	        $directory = dirname($path);
155	        $paths = [];
156	        foreach ((new Schema())->strings($value, $context) as $import) {
157	            $paths[] = str_starts_with($import, '/') ? $import : $directory . '/' . $import;
158	        }
159	
160	        return $paths;
161	    }
162	}
