630	    public function testInitRejectsNewDocsIncludingEmptyDirectories(): void
631	    {
632	        $root = sys_get_temp_dir() . '/guard-disable-doc-' . uniqid();
633	        mkdir($root . '/vendor/example/docs', 0777, true);
634	        mkdir($root . '/packages/example/docs', 0777, true);
635	        $output = '';
636	        $app = new Application($root, static function (string $text) use (&$output): void {
637	            $output .= $text;
638	        });
639	        self::assertSame(0, $app->run(['init']));
640	        self::assertStringContainsString('disable-doc.yaml', (string) file_get_contents($root . '/guard.yaml'));
641	        file_put_contents($root . '/README.md', "# Project\n");
642	        self::assertSame(0, $app->run(['check']));
643	        mkdir($root . '/docs');
644	        $output = '';
645	        self::assertSame(1, $app->run(['check']));
646	        self::assertStringContainsString('structure.denied_dir', $output);
647	        self::assertStringContainsString('Directory "docs" matches denied pattern "docs". Rename or remove it.', $output);
648	        file_put_contents($root . '/docs/guide.md', "# Guide\n");
649	        self::assertSame(1, $app->run(['check']));
650	        self::assertSame(1, $app->run(['fix', '--dry-run']));
651	        self::assertSame(1, $app->run(['fix']));
652	        self::assertSame("# Guide\n", file_get_contents($root . '/docs/guide.md'));
653	    }
