724	    public function testRunChecksDryRunsAppliesAndIsIdempotent(): void
725	    {
726	        $root = sys_get_temp_dir() . '/guard-cli-' . uniqid();
727	        mkdir($root);
728	        file_put_contents($root . '/app.json', '{"workers":0,"other":"keep"}');
729	        file_put_contents($root . '/guard.yaml', "version: 1\nconfiguration:\n  - id: workers\n    file: app.json\n    select: /workers\n    assert: {min: 1}\n    repair: 1\n");
730	        $output = '';
731	        $app = new Application($root, static function (string $text) use (&$output): void {
732	            $output .= $text;
733	        });
734	        self::assertSame(1, $app->run(['check']));
735	        self::assertSame('{"workers":0,"other":"keep"}', file_get_contents($root . '/app.json'));
736	        self::assertSame(0, $app->run(['fix', '--dry-run']));
737	        self::assertSame('{"workers":0,"other":"keep"}', file_get_contents($root . '/app.json'));
738	        self::assertSame(0, $app->run(['fix']));
739	        self::assertSame(['workers' => 1, 'other' => 'keep'], json_decode((string) file_get_contents($root . '/app.json'), true, 512, JSON_THROW_ON_ERROR));
740	        $after = file_get_contents($root . '/app.json');
741	        self::assertSame(0, $app->run(['fix']));
742	        self::assertSame($after, file_get_contents($root . '/app.json'));
743	        self::assertStringContainsString('workers', $output);
744	    }
