13	/**
14	 * The public guard command boundary.
15	 *
16	 * It builds the Symfony Console application for a project directory and
17	 * runs it in-process, writing to the process streams or to one injected sink.
18	 */
19	final class Application
20	{
21	    /**
22	     * @param ?Closure(string): void $output receives standard output and standard error, or null for the process streams
23	     */
24	    public function __construct(private string $directory, private ?Closure $output = null, private ?Registry $registry = null)
25	    {
26	    }
27	    /**
28	     * @param list<string> $arguments arguments without the executable name
29	     */
30	    public function run(array $arguments): int
31	    {
32	        return $this->console()->doRun(new ArgvInput(array_merge(['guard'], $arguments)), $this->output());
33	    }
34	    /**
35	     * Builds the console application with the guard commands.
36	     */
37	    public function console(): GuardConsole
38	    {
39	        return new GuardConsole($this->directory, $this->registry);
40	    }
41	    /**
42	     * Returns the output the run writes to: the process streams, or the injected sink.
