135	                throw new PolicyException('Duplicate configuration rule "' . $rule['id'] . '" in ' . $path . '. Give each rule a unique id in that file.');
136	            }
137	            $seen[$rule['id']] = true;
138	        }
139	    }
140	
141	    /**
142	     * Resolves import paths from the directory of the file that lists them.
143	     *
144	     * @param mixed $value
145	     * @return list<string>
146	     * @throws PolicyException when imports is not a list of paths
147	     */
148	    public function imports($value, string $path, bool $root): array
149	    {
150	        if ($value === null) {
151	            return [];
152	        }
153	        $context = ($root ? 'guard.yaml' : basename($path)) . '.imports';
154	        $directory = dirname($path);
155	        $paths = [];
156	        foreach ((new Schema())->strings($value, $context) as $import) {
157	            $paths[] = str_starts_with($import, '/') ? $import : $directory . '/' . $import;
158	        }
159	
160	        return $paths;
161	    }
162	}
