5	namespace Guard\Reporting;
6	
7	use Guard\Diagnostic\Finding;
8	use Guard\Policy\FileChange;
9	use Guard\Reporting\Filtering\ReportScope;
10	use JsonException;
11	use Symfony\Component\Console\Formatter\OutputFormatter;
12	
13	/**
14	 * Renders human diagnostics, compact AI diagnostics and structured reports.
15	 */
16	final class Reporter
17	{
18	    /**
19	     * @param list<Finding> $findings
20	     */
21	    public function hasErrors(array $findings): bool
22	    {
23	        foreach ($findings as $finding) {
24	            if ($finding->level === 'required') {
25	                return true;
26	            }
27	        }
28	        return false;
29	    }
30	
31	    /**
32	     * @param list<Finding> $findings
33	     * @param list<FileChange> $changes
34	     * @throws JsonException
35	     */
36	    public function render(array $findings, array $changes, string $format, string $action, bool $decorated = false, ?ReportScope $scope = null): string
37	    {
38	        $rows = [];
39	        foreach ($findings as $finding) {
40	            $rows[] = ['path' => $finding->path, 'rule' => $finding->rule, 'level' => $finding->level === 'required' ? 'error' : 'warning',
41	                'message' => $finding->message, 'fixable' => $finding->fixable];
42	        }
43	        $diffs = [];
44	        foreach ($changes as $change) {
45	            $diffs[] = ['path' => $change->path, 'diff' => (new ChangeDiff())->render($change)];
46	        }
47	        if ($format === 'json') {
48	            return json_encode(['findings' => $rows, 'changes' => array_column($diffs, 'path'), 'diffs' => $diffs,
49	                'action' => $action, 'success' => !$this->hasErrors($scope === null ? $findings : $scope->findings), 'summary' => $this->counts($findings)] + ($scope === null ? [] : [
50	                    'selection' => ['shown' => count($findings), 'total' => count($scope->findings), 'hidden' => count($scope->findings) - count($findings)],
51	                    'totalSummary' => $this->counts($scope->findings),
52	                    'baseline' => $scope->baseline === null ? null : ['path' => $scope->baseline, 'suppressed' => $scope->suppressed, 'unmatched' => $scope->unmatched],
53	                ]), JSON_THROW_ON_ERROR | JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n";
54	        }
55	        if ($format === 'ai') {
56	            return $this->ai($findings, $changes, $action, $scope);
57	        }
58	        return $this->human($findings, $changes, $action, $decorated, $scope);
59	    }
60	
61	    /**
62	     * @param list<Finding> $findings
63	     * @return array{errors: int, warnings: int, fixable: int}
64	     */
65	    public function counts(array $findings): array
66	    {
67	        $counts = ['errors' => 0, 'warnings' => 0, 'fixable' => 0];
68	        foreach ($findings as $finding) {
69	            ++$counts[$finding->level === 'required' ? 'errors' : 'warnings'];
70	            if ($finding->fixable) {
71	                ++$counts['fixable'];
72	            }
73	        }
74	        return $counts;
75	    }
76	
77	    /**
78	     * @param list<Finding> $findings
79	     * @param list<FileChange> $changes
80	     */
81	    public function ai(array $findings, array $changes, string $action, ?ReportScope $scope = null): string
82	    {
83	        $lines = [];
84	        foreach ($findings as $finding) {
85	            $lines[] = sprintf('%s: %s [%s] fixable=%s %s', $finding->level === 'required' ? 'error' : 'warning', $finding->path, $finding->rule, $finding->fixable ? 'yes' : 'no', $finding->message);
86	        }
87	        foreach ($changes as $change) {
88	            $lines[] = $action . ': ' . $change->path;
89	            $lines[] = rtrim((new ChangeDiff())->render($change), "\n");
90	        }
91	        $lines[] = $this->actionNote($action);
92	        $lines[] = $this->summary($findings, $changes, $action, ', ') . '.';
93	        $lines[] = $scope === null ? '' : $scope->note(count($findings));
94	        $lines[] = $this->hasErrors($scope === null ? $findings : $scope->findings) ? 'Guard found required violations.' : 'Guard passed.';
95	        return implode("\n", array_filter($lines, static fn (string $line): bool => $line !== '')) . "\n";
96	    }
97	
98	    /**
99	     * @param list<Finding> $findings
100	     * @param list<FileChange> $changes
101	     */
102	    public function human(array $findings, array $changes, string $action, bool $decorated, ?ReportScope $scope = null): string
103	    {
104	        $formatter = new OutputFormatter($decorated);
105	        $title = $action === 'checked' ? 'Guard check' : 'Guard fix';
106	        $lines = ['', '<options=bold>' . $title . '</>', ''];
107	        $groups = [];
108	        foreach ($findings as $finding) {
109	            $groups[$finding->path][] = $finding;
110	        }
111	        foreach ($groups as $group) {
112	            $lines[] = '<options=bold>' . OutputFormatter::escape($group[0]->path) . '</>';
113	            foreach ($group as $finding) {
114	                $level = $finding->level === 'required' ? 'error' : 'warning';
115	                $color = $finding->level === 'required' ? 'red' : 'yellow';
116	                $lines[] = sprintf('  <fg=%s>%s:</> %s  <fg=cyan>%s</>', $color, $level, OutputFormatter::escape($finding->rule), $finding->fixable ? 'fixable' : 'manual');
117	                $lines[] = '    ' . OutputFormatter::escape($finding->message);
118	            }
119	            $lines[] = '';
120	        }
121	        foreach ($changes as $change) {
122	            $lines[] = '<options=bold>' . OutputFormatter::escape($action . ': ' . $change->path) . '</>';
123	            foreach (explode("\n", rtrim((new ChangeDiff())->render($change), "\n")) as $line) {
124	                $color = str_starts_with($line, '+') ? 'green' : (str_starts_with($line, '-') ? 'red' : 'default');
125	                $lines[] = '  <fg=' . $color . '>' . OutputFormatter::escape($line) . '</>';
126	            }
127	            $lines[] = '';
128	        }
129	        $counts = $this->counts($findings);
130	        $lines[] = '<options=bold>' . $this->summary($findings, $changes, $action, ' · ') . '</>';
131	        if ($this->actionNote($action) !== '') {
132	            $lines[] = $this->actionNote($action);
133	        }
134	        if ($counts['fixable'] > 0 && $action === 'checked') {
135	            $lines[] = 'Preview repairs: guard fix --dry-run';
136	        }
137	        if ($scope !== null && $scope->note(count($findings)) !== '') {
138	            $lines[] = OutputFormatter::escape($scope->note(count($findings)));
139	        }
140	        $lines[] = $this->hasErrors($scope === null ? $findings : $scope->findings) ? '<fg=red>Guard found required violations.</>' : '<fg=green>Guard passed.</>';
141	        return $formatter->format(implode("\n", $lines) . "\n") ?? '';
142	    }
143	
144	    /**
145	     * @param list<Finding> $findings
146	     * @param list<FileChange> $changes
147	     */
148	    public function summary(array $findings, array $changes, string $action, string $separator): string
149	    {
150	        $counts = $this->counts($findings);
151	        $files = $action === 'checked' ? count(array_unique(array_map(static fn (Finding $finding): string => $finding->path, $findings))) : count($changes);
152	        return implode($separator, [
153	            $counts['errors'] . ($counts['errors'] === 1 ? ' error' : ' errors'),
154	            $counts['warnings'] . ($counts['warnings'] === 1 ? ' warning' : ' warnings'),
155	            $counts['fixable'] . ' fixable',
156	            $files . ($files === 1 ? ' file ' : ' files ') . ($action === 'checked' ? 'with findings' : $action),
157	        ]);
158	    }
159	
160	    /**
161	     * Explains whether the plan was written, previewed, or blocked.
162	     */
163	    public function actionNote(string $action): string
164	    {
165	        return match ($action) {
166	            'blocked' => 'Repairs blocked by required configuration violations. No files were written; diffs show the proposed changes.',
167	            'would change' => 'Dry run: no files were written. Run guard fix to apply these changes.',
168	            default => '',
169	        };
170	    }
171	}
