648	    public function testRegisteredPolicyDeclaresFilesAndCliReportsItsFindings(): void
649	    {
650	        $project = new class (['guard.yaml' => "version: 1\nstructure: {paths: [.], directories: []}\n"]) {
651	            public string $root;
652	            /**
653	             * @param array<array-key, string> $files
654	             */
655	            public function __construct(array $files = [])
656	            {
657	                $this->root = sys_get_temp_dir() . '/guard-contract-' . uniqid('', true);
658	                mkdir($this->root);
659	                foreach ($files as $path => $source) {
660	                    $this->write((string) $path, $source);
661	                }
662	            }
663	            public function write(string $path, string $source): void
664	            {
665	                $directory = dirname($this->root . '/' . $path);
666	                if (!is_dir($directory)) {
667	                    mkdir($directory, 0777, true);
668	                }
669	                file_put_contents($this->root . '/' . $path, $source);
670	            }
671	            public function remove(): void
672	            {
673	                foreach (new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->root, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST) as $file) {
674	                    if ($file instanceof SplFileInfo) {
675	                        if ($file->isDir() && !$file->isLink()) {
676	                            rmdir($file->getPathname());
677	                        } else {
678	                            unlink($file->getPathname());
679	                        }
680	                    }
681	                }
682	                rmdir($this->root);
683	            }
684	        };
685	        try {
686	            $registry = Registry::defaults();
687	            $registry->addPolicy('readme', new class (['readme' => new Input(new Selection('files', ['README.md'], [], '', false, ''), null)], static function (InputSet $inputs, Context $context): Plan {
688	                $file = $inputs->get('readme')->files['README.md'] ?? null;
689	                $exists = $file === null || $file->file->entry->file;
690	                return new Plan($exists ? [] : [new Finding('README.md', 'readme.required', 'required', 'Create README.md.')], []);
691	            }) implements Policy
692	            {
693	                /** @param array<string, Input> $inputs
694	                 * @param Closure(InputSet, Context): Plan $callback
695	                 */
696	                public function __construct(private array $inputs, private Closure $callback)
697	                {
698	                }
699	                public function inputs(Context $context): array
700	                {
701	                    return $this->inputs;
702	                }
703	                public function evaluate(InputSet $inputs, Context $context): Plan
704	                {
705	                    return ($this->callback)($inputs, $context);
706	                }
707	            });
708	
709	            $output = '';
710	            $app = new Application($project->root, static function (string $text) use (&$output): void {
711	                $output .= $text;
712	            }, $registry);
713	            self::assertSame(1, $app->run(['check', '--format=ai']));
714	            self::assertStringContainsString('[readme.required]', $output);
715	            $project->write('README.md', '# Project');
716	            self::assertSame(0, $app->run(['check']));
717	        } finally {
718	            $project->remove();
719	        }
720	    }
