722	    public function testConfiguredPoliciesAndStructurersShareScopeAndCanRunRepeatedly(): void
723	    {
724	        $structurer = new class () implements Structurer {
725	            public function __construct(private string $prefix = '')
726	            {
727	            }
728	            public function structure(Source $source): Text
729	            {
730	                return new Text($this->prefix . $source->text());
731	            }
732	        };
733	        $policy = new class () implements Policy {
734	            public function __construct(private string $structure = 'text', private string $expected = 'ok')
735	            {
736	            }
737	            public function inputs(Context $context): array
738	            {
739	                return ['text' => new Input(new Selection('patterns', ['*.txt']), $this->structure)];
740	            }
741	            /**
742	             * @throws JsonException
743	             * @throws Exception
744	             */
745	            public function evaluate(InputSet $inputs, Context $context): Plan
746	            {
747	                $findings = [];
748	                foreach ($inputs->get('text')->files as $path => $file) {
749	                    $text = $file->value();
750	                    if ($text instanceof Text && $text->content() !== $this->expected) {
751	                        $findings[] = new Finding($path, 'app.text', 'required', 'Replace the text with ok.');
752	                    }
753	                }
754	                return new Plan($findings, []);
755	            }
756	        };
757	        $root = sys_get_temp_dir() . '/guard-registration-' . uniqid('', true);
758	        mkdir($root);
759	        try {
760	            file_put_contents($root . '/allowed.txt', 'bad');
761	            file_put_contents($root . '/excluded.txt', 'bad');
762	            file_put_contents($root . '/guard.yaml', Yaml::dump([
763	                'version' => 1,
764	                'collect' => ['include' => ['allowed.txt']],
765	                'extensions' => [
766	                    $policy::class => ['expected' => 'prefix:ok', 'structure' => $structurer::class],
767	                    $structurer::class => ['prefix' => 'prefix:'],
768	                ],
769	            ], 6));
770	            $registry = Registry::defaults();
771	            $output = '';
772	            $app = new Application($root, static function (string $text) use (&$output): void {
773	                $output .= $text;
774	            }, $registry);
775	            for ($run = 0; $run < 2; ++$run) {
776	                $output = '';
777	                self::assertSame(1, $app->run(['check', '--format=json']));
778	                self::assertStringContainsString('allowed.txt', $output);
779	                self::assertStringContainsString('app.text', $output);
780	                self::assertStringNotContainsString('excluded.txt', $output);
781	            }
782	            self::assertSame([], $registry->policies());
783	            self::assertArrayNotHasKey($structurer::class, $registry->structures());
784	            file_put_contents($root . '/allowed.txt', 'ok');
785	            self::assertSame(0, $app->run(['check']));
786	        } finally {
787	            unlink($root . '/guard.yaml');
788	            unlink($root . '/allowed.txt');
789	            unlink($root . '/excluded.txt');
790	            rmdir($root);
791	        }
792	    }
793	}
