                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "For a score: the level descriptions from lowest (0) to highest."
                },
                "threshold": {
                    "type": "number",
                    "minimum": 0,
                    "maximum": 1,
                    "description": "The probability (predicate) or confidence (choice, score) a violation needs; 0.5 when omitted."
                }
            }
        },
        "violation": {
